For any $\delta\in (0,1)$, we have
\begin{equation}
\begin{aligned}
P\Bigg (& E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]-E_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\leq \left\vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\right\vert \sqrt{\frac{2\log(\frac{SAHK}{\delta})}{\max\{1,N^k_h(s,a)\}}},\\
&V_{h+1}^*:\mathcal{S}\to [0,H-h],\lambda_{h+1}^*\in [0,H-h],\forall (s,a,h,k)\in \mathcal{S}\times \mathcal{A}\times [H]\times [K]\Bigg)\geq 1-\delta.
\end{aligned}
\end{equation}

For any $\delta\in (0,1)$, we have that 
\begin{equation}
\begin{aligned}
P\Bigg( & OCE^{u}_{s'\sim P_h(\cdot\vert s,a)}(V_{h+1}^*(s'))-OCE^{u}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(V_{h+1}^*(s')) \leq \vert u(-H+h)\vert\sqrt{\frac{2\log\left (\frac{SAHK}{\delta}\right )}{\max\{1,N_h^k(s,a)\}}},\\
&V_{h+1}^*:\mathcal{S}\to [0,H-h],\forall (s,a,h,k)\in \mathcal{S}\times \mathcal{A}\times [H]\times [K]\Bigg)\geq 1-\delta.
\end{aligned}
\end{equation}

For any $\delta\in (0,1)$, we have
\begin{align*}
P\Bigg(\left\Vert \hat{P}_h^k(\cdot\vert s,a)-P_h(\cdot\vert s,a)\right\Vert_1 \leq \sqrt{\frac{2S\log\left(\frac{SAHK}{\delta}\right)}{\max\{1,N_h^k(s,a)\}}}, \forall (s,a,h,k)\in \mathcal{S}\times \mathcal{A}\times [H]\times [K]\Bigg )\geq 1-\delta.
\end{align*}

For any $\delta\in (0,1)$, we have  
\begin{equation}
\begin{aligned}
P\Bigg( & \left\vert OCE^{u}_{s'\sim P_h(\cdot\vert s,a)}(\hat{V}_{h+1}^k(s'))-OCE^{u}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(\hat{V}_{h+1}^k(s')) \right\vert \leq \vert u(-H+h)\vert\sqrt{\frac{2S\log\left (\frac{SAHK}{\delta}\right )}{\max\{1,N_h^k(s,a)\}}},\\
&\forall (s,a,h,k)\in \mathcal{S}\times \mathcal{A}\times [H]\times [K]\Bigg)\geq 1-\delta.
\end{aligned}
\end{equation}

For any $(h,k)\in [H]\times [K]$ and functions $\hat{V}_{h+1}^k,V_{h+1}^{\pi^k},V_{h+1}^{*}:\mathcal{S}\to [0,H-h]$, we have
\begin{equation}
\begin{aligned}
&OCE^{u}_{s_{h+1}^k\sim P_h(\cdot\vert s_h^k,a_h^k)}\left (\hat{V}_{h+1}^k(s_{h+1}^k)\right )-OCE^{u}_{s_{h+1}^k\sim P_h(\cdot\vert s_h^k,a_h^k)}\left (V_{h+1}^{\pi^k}(s_{h+1}^k)\right )\\
&\leq E_{s_{h+1}^k\sim B_h(\cdot\vert s_h^k,a_h^k)}\left [\hat{V}_{h+1}^k(s_{h+1}^k)-V_{h+1}^{\pi^k}(s_{h+1}^k)\right ],
\end{aligned}
\end{equation}
where $B_h(\cdot\vert s_h^k,a_h^k)$ is the new probability measure given in (25).

For each episode $k\in [K]$, we have
\begin{align} 
&\hat{V}_1^k(s_1^k)-V_1^{\pi^k}(s_1^k)\\
&\leq \sum_{h=1}^H E_{(s_h^k,a_h^k)\sim w_{hk}^{B}}\Big [b^k_h(s_h^k,a_h^k)\\
&\quad \quad \quad +OCE^u_{s_{h+1}^k\sim \hat{P}^k_h(\cdot\vert s_h^k,a_h^k)}(\hat{V}_{h+1}^k(s_{h+1}^k))-OCE^u_{s_{h+1}^k\sim P_h(\cdot\vert s_h^k,a_h^k)}(\hat{V}_{h+1}^k(s_{h+1}^k))\Big ]. 
\end{align}

Consider arbitrary $K$ sequences of trajectories $\tau^k=\{s_h^k,a_h^k\}_{h=1}^H$ for $k=1,\cdots,K$, we have
\begin{align*}
\sum_{k=1}^K\frac{1}{\max\{1,N_h^k(s_h^k,a_h^k)\}}\leq  SA\log(3K).
\end{align*}

We have
\begin{align}
& E\left [\sum_{k=1}^K\sum_{h=1}^H E_{(s_h^k,a_h^k)\sim w_{hk}^{B}}\left [\frac{\vert u(-H+h)\vert}{\sqrt{\max\{1,N_h^k(s_h^k,a_h^k)\}}}\right ]\right ]\\
&\leq \sum_{h=1}^H \vert u(-H+h)\vert  \sqrt{\prod\limits_{i=1}^{h-1} u_{-}'(-H+i)SAK\log(3K)},
\end{align}
where $E_{(s_h^k,a_h^k)\sim w_{hk}^{B}}[\cdot]$ given in (30) is taken over $(s_h^k,a_h^k)$ conditional on $(s_1^k,a_1^k)$ and $u_{-}'(\cdot)$ is the left derivative of $u$.

The expected regret of the OCE-VI algorithm satisfies
\begin{align*}
&Regret(\mathcal{M},\textbf{OCE-VI},K)\leq \tilde{\mathcal{O}}\left(\sum_{h=1}^H\vert u(-H+h)\vert S\sqrt{\prod\limits_{i=1}^{h-1} u_{-}'(-H+i)AK}\right),
\end{align*}
where 
$\tilde{\mathcal{O}}(\cdot)$ ignores the logarithmic factors in $S,A,H$ and $K$ and $u'_{-}(\cdot)$ is the left derivative of $u$.
